function biSpan(zh, en, cls, tag) {
var t = tag || 'span';
var cAttr = cls ? (' class="' + cls + '"') : '';
return '<' + t + cAttr + ' data-i18n-zh="' + escapeHtml(zh) + '" data-i18n-en="' + escapeHtml(en || zh) + '">' + escapeHtml(zh) + '</' + t + '>';
}

